import { isRecord } from "./record-shared.mjs";

export const UPDATE_COMPATIBILITY_CHUNK_HEADER =
  "// Generated by update-compat-inventory; do not edit.";

/** @param {string} source */
export function isUpdateCompatibilityChunk(source) {
  return source.startsWith(UPDATE_COMPATIBILITY_CHUNK_HEADER);
}

/** @param {unknown} source @param {unknown} target */
export function supportsUpdateSchemas(source, target) {
  // Historical v1 inventories shipped as admitted-source lists without schema metadata.
  if (source === undefined) {
    return true;
  }
  return (
    isRecord(source) &&
    isRecord(target) &&
    ["state", "agent"].every(
      (key) =>
        typeof source[key] === "number" &&
        Number.isInteger(source[key]) &&
        source[key] >= 0 &&
        typeof target[key] === "number" &&
        Number.isInteger(target[key]) &&
        source[key] <= target[key],
    )
  );
}
